CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY);
CREATE TABLE server_meta(server_id uuid PRIMARY KEY);
CREATE TABLE humans(human_id uuid PRIMARY KEY, status text NOT NULL CHECK(status IN ('active','disabled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE households(household_id uuid PRIMARY KEY, owner_human_id uuid NOT NULL REFERENCES humans, display_label text NOT NULL, revision integer NOT NULL DEFAULT 1 CHECK(revision>0), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')));
CREATE TABLE characters(character_id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES households, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public_identities(public_identity_id uuid PRIMARY KEY, character_id uuid NOT NULL UNIQUE REFERENCES characters, layer text NOT NULL DEFAULT 'surface' CHECK(layer='surface'), display_name text NOT NULL, revision integer NOT NULL DEFAULT 1 CHECK(revision>0), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')));
CREATE TABLE test_principals(principal_id uuid PRIMARY KEY, public_identity_id uuid NOT NULL UNIQUE REFERENCES public_identities, token_hash text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')));
CREATE TABLE stream_state(stream text PRIMARY KEY CHECK(stream='surface'), committed_seq bigint NOT NULL DEFAULT 0 CHECK(committed_seq>=0));
INSERT INTO stream_state(stream) VALUES ('surface');
CREATE TABLE posts(post_id uuid PRIMARY KEY, author_public_identity_id uuid NOT NULL REFERENCES public_identities, body_text text NOT NULL CHECK(octet_length(body_text)<=32768 AND length(trim(body_text))>0), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), created_seq bigint NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'published' CHECK(status='published'), origin text NOT NULL DEFAULT 'test_harness' CHECK(origin='test_harness'));
CREATE TABLE comments(comment_id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts, author_public_identity_id uuid NOT NULL REFERENCES public_identities, reply_to_comment_id uuid CHECK(reply_to_comment_id IS NULL), body_text text NOT NULL CHECK(octet_length(body_text)<=32768 AND length(trim(body_text))>0), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), created_seq bigint NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'published' CHECK(status='published'), origin text NOT NULL DEFAULT 'test_harness' CHECK(origin='test_harness'));
CREATE INDEX comments_timeline ON comments(post_id,created_seq);
CREATE TABLE events(event_id uuid PRIMARY KEY, event_seq bigint NOT NULL UNIQUE, schema_version integer NOT NULL CHECK(schema_version=1), type text NOT NULL CHECK(type IN ('square.post.created','square.comment.created')), layer text NOT NULL CHECK(layer='surface'), actor_public_identity_id uuid NOT NULL REFERENCES public_identities, subject jsonb NOT NULL, context jsonb NOT NULL, visibility text NOT NULL CHECK(visibility='public'), occurred_at timestamptz NOT NULL, origin text NOT NULL CHECK(origin='test_harness'));
CREATE TABLE notifications(notification_id uuid PRIMARY KEY, recipient_public_identity_id uuid NOT NULL REFERENCES public_identities, event_id uuid NOT NULL REFERENCES events, reasons text[] NOT NULL CHECK(reasons=ARRAY['comment_on_own_post']), created_at timestamptz NOT NULL, UNIQUE(recipient_public_identity_id,event_id));
CREATE TABLE idempotency_records(principal_id uuid NOT NULL REFERENCES test_principals, key uuid NOT NULL, request_hash text NOT NULL, resource_id uuid NOT NULL, event_id uuid NOT NULL REFERENCES events, response_status integer NOT NULL CHECK(response_status=201), response_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(principal_id,key));
INSERT INTO schema_migrations VALUES(1);
